      "CREATE TABLE _task_dispatch_receipts_project_backup_0069 AS\n  SELECT id, project_id FROM task_dispatch_receipts WHERE project_id IS NOT NULL;",
      "CREATE TABLE _flight_event_outbox_project_backup_0069 AS\n  SELECT id, project_id FROM flight_event_outbox WHERE project_id IS NOT NULL;",
      "UPDATE task_verdicts SET project_id = NULL WHERE project_id IS NOT NULL;",
