      "CREATE TRIGGER task_dispatch_runtime_receipts_no_delete\nBEFORE DELETE ON task_dispatch_runtime_receipts\nBEGIN\n  SELECT RAISE(ABORT, 'task dispatch runtime receipts are append-only');\nEND;",
